CREATE TABLE organizations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150),
 timezone text NOT NULL DEFAULT 'Africa/Tunis', followup_business_days integer NOT NULL DEFAULT 4 CHECK(followup_business_days BETWEEN 1 AND 60), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), google_sub text UNIQUE NOT NULL, email text UNIQUE NOT NULL CHECK(email=lower(trim(email))), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','member')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id));
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL CHECK(email=lower(trim(email))), role text NOT NULL CHECK(role IN ('admin','member')), token_hash text UNIQUE NOT NULL, invited_by uuid, expires_at timestamptz NOT NULL, accepted_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,invited_by) REFERENCES memberships(organization_id,user_id));
CREATE UNIQUE INDEX invitations_pending ON invitations(organization_id,email) WHERE accepted_at IS NULL AND revoked_at IS NULL;
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), organization_id uuid NOT NULL REFERENCES organizations(id), csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,user_id) REFERENCES memberships(organization_id,user_id));
CREATE INDEX sessions_expiration ON sessions(expires_at);
CREATE TABLE oauth_states (state_hash text PRIMARY KEY, browser_hash text NOT NULL, nonce text NOT NULL, verifier text NOT NULL, invitation_hash text, expires_at timestamptz NOT NULL);
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150), sector text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', owner_user_id uuid, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES memberships(organization_id,user_id));
CREATE UNIQUE INDEX company_name_unique ON companies(organization_id,lower(trim(name))) WHERE archived_at IS NULL;
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), company_id uuid, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150), job_title text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', owner_user_id uuid, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES memberships(organization_id,user_id));
CREATE TABLE contact_emails (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), contact_id uuid NOT NULL, email text NOT NULL CHECK(email=lower(trim(email))), UNIQUE(organization_id,email), FOREIGN KEY(organization_id,contact_id) REFERENCES contacts(organization_id,id) ON DELETE CASCADE);
CREATE TABLE notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), company_id uuid, contact_id uuid, author_user_id uuid NOT NULL, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 10000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((company_id IS NOT NULL)::int+(contact_id IS NOT NULL)::int=1), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,contact_id) REFERENCES contacts(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,author_user_id) REFERENCES memberships(organization_id,user_id));
CREATE TABLE followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), company_id uuid, contact_id uuid, owner_user_id uuid NOT NULL, subject text NOT NULL CHECK(length(trim(subject)) BETWEEN 1 AND 300), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','cancelled')), cancellation_reason text NOT NULL DEFAULT '', local_draft text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id), FOREIGN KEY(organization_id,contact_id) REFERENCES contacts(organization_id,id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES memberships(organization_id,user_id));
CREATE INDEX followups_due ON followups(organization_id,status,due_at);
CREATE TABLE activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_user_id uuid NOT NULL, entity_type text NOT NULL, entity_id uuid, action text NOT NULL, summary text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,actor_user_id) REFERENCES memberships(organization_id,user_id));
CREATE INDEX activities_recent ON activities(organization_id,created_at DESC);
CREATE TABLE contact_card_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), contact_id uuid NOT NULL, uploaded_by uuid NOT NULL, mime_type text NOT NULL CHECK(mime_type IN ('image/jpeg','image/png','image/webp')), data bytea NOT NULL CHECK(octet_length(data)<=8388608), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,contact_id) REFERENCES contacts(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,uploaded_by) REFERENCES memberships(organization_id,user_id));
CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','contacts','notes','followups'] LOOP EXECUTE format('CREATE TRIGGER touch_updated BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','contacts','contact_emails','notes','followups','activities','contact_card_images'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (organization_id = nullif(current_setting(''app.organization_id'',true),'''')::uuid) WITH CHECK (organization_id = nullif(current_setting(''app.organization_id'',true),'''')::uuid)',t);
 END LOOP; END $$;
